-- Access QueryDef: 24-08_DiagrammObc_01
-- Type: 0

SELECT x.ogNm, x.branchName_Sort, x.cstAgPnCode_sort, x.branch, x.dateRslt, x.ogaKey, x.ogNm_hook, x.countBranch_, x.branchName, x.branchName_hook, x.cstAgPnCode_hook, [24-08_DiagrammObc_01_lim].ag_lim, [24-08_DiagrammObc_01_lim].iv_lim, [24-08_DiagrammObc_01_lim].uk_lim
FROM (SELECT qq.ogNm, qq.branchName_Sort, qq.cstAgPnCode_sort, qq.branch, dd.ddd AS dateRslt, qq.ogaKey, qq.ogNm_hook, qq.countBranch_, qq.branchName, qq.branchName_hook, qq.cstAgPnCode_hook FROM (SELECT q.ogNm, q.branchName_Sort, q.cstAgPnCode_sort, q.branch, q.ogaKey, q.ogNm_hook, q.countBranch_, q.branchName, q.branchName_hook, q.cstAgPnCode_hook FROM [24-08_DiagrammObc] AS q GROUP BY q.ogNm, q.branchName_Sort, q.cstAgPnCode_sort, q.branch, q.ogaKey, q.ogNm_hook, q.countBranch_, q.branchName, q.branchName_hook, q.cstAgPnCode_hook)  AS qq, [24-08_DiagrammObc_ddd] AS dd GROUP BY qq.ogNm, qq.branchName_Sort, qq.cstAgPnCode_sort, qq.branch, dd.ddd, qq.ogaKey, qq.ogNm_hook, qq.countBranch_, qq.branchName, qq.branchName_hook, qq.cstAgPnCode_hook)  AS x LEFT JOIN [24-08_DiagrammObc_01_lim] ON (x.cstAgPnCode_sort = [24-08_DiagrammObc_01_lim].cstAgPnCode_sort) AND (x.branchName_Sort = [24-08_DiagrammObc_01_lim].branchName_Sort) AND (x.ogNm = [24-08_DiagrammObc_01_lim].ogNm);
